// Extract data from Francis webhook
const conversationId = $input.item.json.conversation_id;
const customerId = $input.item.json.customer_id;
const extractedData = $input.item.json.extracted_data;

return {
  json: {
    conversation_id: conversationId,
    customer_id: customerId,
    gstin: extractedData.gstin,
    pan: extractedData.pan,
    consent_obtained: extractedData.consent_obtained,
    loan_amount_lakhs: extractedData.loan_amount_lakhs,
    loan_purpose: extractedData.loan_purpose,
    tenure_months: extractedData.tenure_months,
    collateral_available: extractedData.collateral_available,
    customer_priority: extractedData.customer_priority
  }
};

// Combine all data sources into Nikita request format
// Access merged data - items contain results from parallel API calls
const items = $input.all();

// Find the data from each source by checking for specific keys
let fameScoreData = {};
let creditBureauData = {};
let gstData = {};
let udyamData = {};
let originalParams = {};

for (const item of items) {
  const data = item.json;
  if (data.conversation_id) {
    originalParams = data;
  } else if (data.data && data.data.entity_information) {
    fameScoreData = data.data;
  } else if (data.data && data.data.commercial) {
    creditBureauData = data.data;
  } else if (data.data && data.data.gstin) {
    gstData = data.data;
  } else if (data.data && data.data.udyam_number) {
    udyamData = data.data;
  }
}

// Build gst_data in the format Nikita expects (from FameScore report)
const nikitaGstData = {
  entity_information: fameScoreData.entity_information || {},
  bank_details: fameScoreData.bank_details || [],
  gst_sales_data: fameScoreData.gst_sales_data || {},
  gst_purchase_data: fameScoreData.gst_purchase_data || {},
  compliance: fameScoreData.compliance || {},
  bank_limit_eligibility: fameScoreData.bank_limit_eligibility || {}
};

// Build credit_bureau in the format Nikita expects
const nikitaCreditBureau = {
  commercial: fameScoreData.credit_bureau_commercial || creditBureauData.commercial || {},
  consumer: fameScoreData.credit_bureau_consumer || creditBureauData.consumer || {},
  existing_facilities: fameScoreData.existing_facilities || creditBureauData.existing_facilities || [],
  closed_loans: fameScoreData.closed_loans || creditBureauData.closed_loans || []
};

// Build pan_data from FameScore
const nikitaPanData = {
  pan: fameScoreData.entity_information?.pan || originalParams.pan,
  name: fameScoreData.entity_information?.legal_name,
  status: 'active',
  category: 'company'
};

// Build customer_inputs in the format Nikita expects
const customerInputs = {
  loan_amount_requested: originalParams.loan_amount_lakhs,
  loan_purpose: originalParams.loan_purpose,
  loan_purpose_description: '',
  tenure_preference_months: originalParams.tenure_months || 36,
  collateral_available: originalParams.collateral_available || false,
  collateral_type: 'none',
  collateral_value: 0,
  priority: originalParams.customer_priority || 'low_interest',
  urgency: '2_weeks'
};

return {
  json: {
    conversation_id: originalParams.conversation_id,
    gst_data: nikitaGstData,
    pan_data: nikitaPanData,
    credit_bureau: nikitaCreditBureau,
    bank_statements: fameScoreData.sales_to_banking_credit ? {
      total_credits_lakhs: fameScoreData.bank_limit_eligibility?.total_12_month_sales || 0,
      bank_to_turnover_ratio: 1.0,
      inward_bounces: 0,
      outward_bounces: 0,
      average_monthly_balance_lakhs: 5.5
    } : null,
    udyam_data: fameScoreData.udyam_registration || udyamData || null,
    itr_data: fameScoreData.itr_data || null,
    customer_inputs: customerInputs
  }
};

// Save CAM to database and prepare for Kesha
const camResponse = $input.item.json;
const camData = camResponse.cam_data || {};

// Transform CAM data to Kesha's AnonymizedCAM format
const keshaPayload = {
  cam_id: camResponse.cam_id,
  conversation_id: camResponse.conversation_id || camData.conversation_id,

  // business_profile mapping
  business_profile: {
    industry_sector: camData.business_profile?.industry_sector || 'IT_services',
    nic_code: camData.business_profile?.nic_code || 'NIC 224',
    years_in_business: camData.business_profile?.years_in_business || 3,
    vintage_years: camData.business_profile?.years_in_business || 3,
    employee_count: camData.business_profile?.employee_count || 50,
    enterprise_type: camData.business_profile?.enterprise_type || 'micro'
  },

  // financial_metrics mapping (from financial_summary)
  financial_metrics: {
    annual_turnover_lakhs: camData.financial_summary?.turnover?.annual_lakhs || 0,
    monthly_average_lakhs: camData.financial_summary?.turnover?.monthly_average_lakhs || 0,
    turnover_growth_yoy: (camData.financial_summary?.turnover?.growth_yoy_pct || 0) / 100,
    profit_margin: (camData.financial_summary?.profitability?.net_profit_margin_pct || 0) / 100,
    net_profit_lakhs: camData.financial_summary?.profitability?.net_profit_lakhs || 0,
    bank_to_turnover_ratio: camData.financial_summary?.banking_behavior?.bank_to_turnover_ratio || 1.0
  },

  // credit_profile mapping
  credit_profile: {
    commercial_score: camData.credit_profile?.commercial_bureau?.score || 'CMR-5',
    total_outstanding_lakhs: camData.credit_profile?.commercial_bureau?.total_outstanding_lakhs || 0,
    overdue_amount_lakhs: camData.credit_profile?.commercial_bureau?.overdue_amount_lakhs || 0,
    active_loans_count: camData.credit_profile?.commercial_bureau?.active_loans || 0,
    existing_facilities: camData.credit_profile?.existing_facilities || [],
    utilization_pct: 0.5
  },

  // compliance mapping (from compliance_status)
  compliance: {
    filing_consistency: camData.compliance_status?.gst?.filing_consistency || 0.84,
    delayed_filings_count: camData.compliance_status?.gst?.delayed_filings_count || 0,
    itr_filed_on_time: camData.compliance_status?.itr?.filed_on_time || true
  },

  // loan_request mapping
  loan_request: camData.loan_request || {},

  // customer_preferences mapping
  customer_preferences: camData.customer_preferences || {}
};

return {
  json: {
    cam_id: camResponse.cam_id,
    cam_data: camData,
    conversation_id: keshaPayload.conversation_id,
    kesha_payload: keshaPayload
  }
};

// Save assessment to database and notify Francis
const assessment = $input.item.json;

// In production, save to assessment_results table
// Then notify Francis to update conversation

return {
  json: {
    conversation_id: $node["Save CAM to Database"].json.conversation_id,
    assessment_id: assessment.assessment_id,
    overall_eligibility: assessment.overall_eligibility,
    max_eligible_amount: assessment.max_eligible_amount_lakhs,
    top_lenders: assessment.lender_matches.slice(0, 3).map(l => l.lender_name),
    customer_report: assessment.customer_report
  }
};

// Error handler - notify Francis about workflow failure
const error = $input.item.json.error || 'Unknown error occurred';
const conversation_id = $execution.customData?.conversation_id || 'unknown';

return {
  json: {
    conversation_id: conversation_id,
    assessment_id: 'error',
    overall_eligibility: 'error',
    max_eligible_amount: 0,
    top_lenders: [],
    customer_report: {
      summary: 'We encountered an issue processing your application. Our team has been notified and will contact you shortly.',
      error_details: error,
      next_steps: ['Our team will review your application manually', 'You will receive an update within 24 hours']
    }
  }
};
